	"streak/internal/db"
	"streak/internal/httpapi"
	"streak/internal/nudges"
	"streak/internal/period"
)

// MaxAgeDays: a check-in may be dated at most this many days before today (R75).
const MaxAgeDays = 60

// Register adds the check-in routes of a habit.
func Register(r httpapi.Routes) {
	h := handler{d: r.Deps}
	r.Member.POST("/habits/:id/completions", httpapi.Handle(h.create))
	r.Member.GET("/habits/:id/completions", httpapi.Handle(h.list))
	r.Member.DELETE("/habits/:id/completions/:cid", httpapi.Handle(h.remove))
	r.Member.POST("/completions/batch", httpapi.Handle(h.batch))
}

// MaxBatch is the most items a batch takes (R83).
const MaxBatch = 100

// BatchResult is one item's answer in a batch.
type BatchResult struct {
	ID         string             `json:"id"`
	Status     string             `json:"status"`
	Code       string             `json:"code,omitempty"`
	Completion *db.CompletionJSON `json:"completion,omitempty"`
}

// refusalCode is the error code a single create would answer for err, or "" for an
// error that is not a refusal.
func refusalCode(err error) string {
	var e *httpapi.Error
	switch {
	case errors.As(err, &e):
		return e.Code
	case errors.Is(err, db.ErrNotFound):
		return "not_found"
	}
	return ""
}

// batch is POST /v1/completions/batch (R83-R85): items in order, each as a single create
// would, a rejected one writing nothing (its own savepoint) and not stopping the others.
func (h handler) batch(c *gin.Context) error {
	who := httpapi.CallerOf(c)
	b, err := httpapi.ReadBody(c)
	if err != nil {
		return err
	}
	var raw []json.RawMessage
	if !b.Has("items") || json.Unmarshal(b["items"], &raw) != nil || len(raw) < 1 ||
		len(raw) > MaxBatch {
		return httpapi.Invalid("items", "items must hold 1 to 100 check-ins")
	}
	items := make([]httpapi.Body, len(raw))
	for i, r := range raw {
		if json.Unmarshal(r, &items[i]) != nil || items[i] == nil {
			return httpapi.Invalid("items", "every item must be an object")
		}
	}
	now, today, err := h.d.Today(c, who.Timezone)
	if err != nil {
		return err
	}
	results := make([]BatchResult, len(items))
	err = h.d.Tx(c, func(tx *gorm.DB) error {
		if _, err := db.LockUser(tx, who.UserID); err != nil {
			return err
		}
		for i, item := range items {
			res := BatchResult{Status: "rejected"}
			res.ID, _, _ = item.UUID("id")
			var out db.Completion
			var existing bool
			err := tx.Transaction(func(sp *gorm.DB) error {
				in, err := ReadInput(item)
				if err != nil {
					return err
				}
				habitID, err := item.RequiredUUID("habit_id")
				if err != nil {
					return err
				}
				habit, err := db.OwnedHabit(sp, who.UserID, habitID)
				if err != nil {
					return err
				}
				out, existing, err = Create(sp, who.UserID, habit, in, now, today)
				if err != nil || existing {
					return err
				}
				return nudges.AfterCheckIn(sp, who.UserID, habit.ID, now, today)
			})
			if err != nil {
				if res.Code = refusalCode(err); res.Code == "" {
					return err
				}
			} else {
				body := db.CompletionBody(out)
				res.Completion, res.Status = &body, "created"
				if existing {
					res.Status = "existing"
				}
			}
			results[i] = res
		}
		return nil
	})
	if err != nil {
		return err
	}
	c.JSON(http.StatusOK, gin.H{"results": results})
	return nil
}

type handler struct{ d httpapi.Deps }

// Input is one check-in to create: {id, date, note?}.
type Input struct {
	ID   string
	Date time.Time
	Note *string
}

// ReadInput validates a check-in body (R43, R77); field names are the body's.
func ReadInput(b httpapi.Body) (Input, error) {
