	var err error
	if in.ID, err = b.RequiredUUID("id"); err != nil {
		return in, err
	}
	d, ok, err := b.Date("date")
	if err != nil || !ok {
		return in, httpapi.Invalid("date", "date must be a YYYY-MM-DD date")
	}
	in.Date = d
	note, ok, err := b.Str("note")
